={{ (() => {
 const reservation=$('ReserveRepeatBusiness').first().json;
 const source=$prevNode.name;
 const preflight=["ValidateReservation","CheckShopifyLive","ValidateShopifyAndConsent","CheckTrelloLive","BuildValidatedMikaMail"].includes(source);
 const payload={p_id:reservation.id,p_claim_token:reservation.claim_token,p_outcome:preflight?'preflight_failed':'unknown',p_reason:preflight?'pre_send_check_failed':'provider_or_validation_failed_no_retry'};
 if(preflight){
  const message=String(($json.error && $json.error.message)||$json.error||$json.message||'');
  const known=["trello_batch_invalid_json","trello_batch_missing","internal_trello_read_failed","trello_batch_incomplete","trello_search_failed","invalid_reservation","invalid_recipient","recipient_scope_mismatch","shopify_live_check_failed","organization_order_coverage_missing"];
  const code=known.find(value=>message.includes(value))||'provider_read_failed';
  payload.p_message={source_node:source,error_code:code};
 }
 return JSON.stringify(payload);
})() }}

